
local yr=[==[]==]
local ilq=
(function(...)
local beo={218,138,29,27,92,209,107,227,116,12,78,152,124,68,252,124,57,181,133,8,45,236,34,179}
local degs=bit32 or bit
local wburz=degs.bxor
for pdqd=1,#beo do beo[pdqd]=wburz(beo[pdqd],(2*pdqd+219)%256) end
local kptoj="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local oulis={}
for bi=1,#kptoj do oulis[kptoj:byte(bi)]=bi-1 end
local function sph(str)
  local R={} local acc,nb=0,0
  for hik=1,#str do
    local v=oulis[str:byte(hik)]
    if v then
      acc=acc*64+v; nb=nb+6
      if nb>=8 then nb=nb-8; R[#R+1]=math.floor(acc/2^nb)%256; acc=acc%2^nb end
    end
  end
  return R
end
local function mzwbd(key,data)
  local S={} for lb=0,255 do S[lb]=lb end
  local j=0
  for xq=0,255 do
    j=(j+S[xq]+key[(xq%#key)+1])%256
    S[xq],S[j]=S[j],S[xq]
  end
  local O={} local ii=0; j=0
  for n=1,#data do
    ii=(ii+1)%256; j=(j+S[ii])%256; S[ii],S[j]=S[j],S[ii]
    O[n]=string.char(wburz(data[n],S[(S[ii]+S[j])%256]))
  end
  return table.concat(O)
end
local code=mzwbd(beo,sph(""))
local nf,ne=(loadstring or load)("return "..code)
if not nf then error(ne or "rage quit chain error") end
local kpw=nf()
return function(big) return kpw(big) end
end)(...)

return ilq(yr)
